// Explicit host allocation boundary: native object sizes are evidence, while
// host_bytes allocates the reconstructed C++ type. The returned bytes are raw.
enum class SingletonAllocationKind { manager, pointer_slots, critical_section, object };
struct SingletonAllocationRequest {
    SingletonAllocationKind kind;
    std::size_t native_bytes;
    std::size_t host_bytes;
};
void* singleton_lifetime_allocate(const SingletonAllocationRequest&);

void* singleton_lifetime_allocate(const SingletonAllocationRequest& request) {
    // 00BF681B: malloc, call the CRT new handler with the allocation size on
    // failure, retry if it returns nonzero, otherwise throw bad_alloc. Host
    // layout requires host_bytes; native_bytes retains the explicit ABI boundary.
    for (;;) {
        if (void* result = std::malloc(request.host_bytes)) {
            return result;
        }
        if (_callnewh(request.host_bytes) == 0) {
            throw std::bad_alloc();
        }
    }
}

